/// `scan(init, body, length)`. `body`'s inputs are, in creation order,
/// the carry, each broadcast, then each per-step slice of `xs`; its one
/// output is the next carry. The body graph is **consumed**.
/// `trajectory` returns every carry stacked (`[length, …init]`).
///
/// - `body`: a body graph, consumed
/// - `xs` (default [])
/// - `bcasts` (default [])
/// - `checkpoints` (default 0)
/// - `trajectory` (default false)
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rlx_graph_scan(
    graph: *mut RlxGraph,
    init: u32,
    body: *mut crate::graph::RlxGraph,
    length: u32,
    xs: *const u32,
    xs_len: usize,
    bcasts: *const u32,
    bcasts_len: usize,
    checkpoints: u32,
    trajectory: bool,
    ret: *mut u32,
) -> i32 {
    guard(|| unsafe {
        if body == graph {
            return Err(ApiError::type_("rlx_graph_scan: `body` cannot be the graph being built"));
        }
        let body = take_graph(body, "rlx_graph_scan body")?;
        let xs = arg::vec(xs, xs_len, "rlx_graph_scan xs")?;
        let bcasts = arg::vec(bcasts, bcasts_len, "rlx_graph_scan bcasts")?;
        let g = graph_mut(graph)?;
        let r = rlx_bind::ops::scan(g, init, body, length, xs, bcasts, checkpoints, trajectory)?;
        out::put(ret, r, "rlx_graph_scan")
    })
}

/// A sub-graph with optional hand-written AD rules (`custom_vjp` /
/// `custom_jvp`). Every body graph passed in is consumed.
///
/// - `fwd_body`: a body graph, consumed
/// - `vjp_body`: optional — `NULL` for none
/// - `jvp_body`: optional — `NULL` for none
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rlx_graph_custom_fn(
    graph: *mut RlxGraph,
    inputs: *const u32,
    inputs_len: usize,
    fwd_body: *mut crate::graph::RlxGraph,
    vjp_body: *mut crate::graph::RlxGraph,
    jvp_body: *mut crate::graph::RlxGraph,
    ret: *mut u32,
) -> i32 {
    guard(|| unsafe {
        if fwd_body == graph {
            return Err(ApiError::type_("rlx_graph_custom_fn: `fwd_body` cannot be the graph being built"));
        }
        if vjp_body == graph {
            return Err(ApiError::type_("rlx_graph_custom_fn: `vjp_body` cannot be the graph being built"));
        }
        if jvp_body == graph {
            return Err(ApiError::type_("rlx_graph_custom_fn: `jvp_body` cannot be the graph being built"));
        }
        let inputs = arg::vec(inputs, inputs_len, "rlx_graph_custom_fn inputs")?;
        let fwd_body = take_graph(fwd_body, "rlx_graph_custom_fn fwd_body")?;
        let vjp_body = if vjp_body.is_null() { None } else { Some(take_graph(vjp_body, "rlx_graph_custom_fn vjp_body")?) };
        let jvp_body = if jvp_body.is_null() { None } else { Some(take_graph(jvp_body, "rlx_graph_custom_fn jvp_body")?) };
        let g = graph_mut(graph)?;
        let r = rlx_bind::ops::custom_fn(g, inputs, fwd_body, vjp_body, jvp_body)?;
        out::put(ret, r, "rlx_graph_custom_fn")
    })
}

/// One node per output of `fwd_body`, which is consumed.
